{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-9T84dV/src/diff.js","content":"/**
 * Line-based diff against a base document, following the exact
 * longest-common-subsequence tie-breaking rule from the specification:
 * walking both documents from the start, a match is taken whenever the
 * current lines are equal, and otherwise the side whose remaining
 * subsequence (after advancing) is at least as long as the other's is
 * advanced, preferring to advance the base on a tie.
 *
 * Returns the changes needed to turn `baseLines` into `sideLines`, each a
 * run of base lines (by index range) replaced by a run of side lines.
 */
export function diffChanges(baseLines, sideLines) {
  const m = baseLines.length
  const n = sideLines.length

  // dp[i][j] = length of the LCS of baseLines[i:] and sideLines[j:], stored
  // flattened with a row stride of (n + 1).
  const stride = n + 1
  const dp = new Int32Array((m + 1) * stride)
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      const idx = i * stride + j
      if (baseLines[i] === sideLines[j]) {
        dp[idx] = 1 + dp[(i + 1) * stride + (j + 1)]
      } else {
        const advanceBase = dp[(i + 1) * stride + j]
        const advanceSide = dp[i * stride + (j + 1)]
        dp[idx] = advanceBase >= advanceSide ? advanceBase : advanceSide
      }
    }
  }

  const changes = []
  let prevB = -1
  let prevS = -1
  let i = 0
  let j = 0

  const flushGap = (curB, curS) => {
    const baseStart = prevB + 1
    const baseEnd = curB
    const sideStart = prevS + 1
    const sideEnd = curS
    if (baseEnd > baseStart || sideEnd > sideStart) {
      changes.push({ baseStart, baseEnd, lines: sideLines.slice(sideStart, sideEnd) })
    }
  }

  while (i < m && j < n) {
    if (baseLines[i] === sideLines[j]) {
      flushGap(i, j)
      prevB = i
      prevS = j
      i++
      j++
    } else {
      const advanceBase = dp[(i + 1) * stride + j]
      const advanceSide = dp[i * stride + (j + 1)]
      if (advanceBase >= advanceSide) {
        i++
      } else {
        j++
      }
    }
  }
  flushGap(m, n)

  return changes
}
"}

