{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-9T84dV/src/regions.js","content":"import { diffChanges } from './diff.js'

function linesEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false
  }
  return true
}

// Reconstructs a side's content across a region's base range, given that
// side's own changes overlapping the region: base lines fill every part of
// the range not covered by one of the side's changes.
function reconstructSide(baseLines, regionStart, regionEnd, ownChanges) {
  const result = []
  let cursor = regionStart
  for (const change of ownChanges) {
    for (let i = cursor; i < change.baseStart; i++) result.push(baseLines[i])
    for (const line of change.lines) result.push(line)
    cursor = change.baseEnd
  }
  for (let i = cursor; i < regionEnd; i++) result.push(baseLines[i])
  return result
}

/**
 * Builds the merge regions for three documents, following the
 * specification: changes from both sides are gathered in base order (mine
 * before theirs on a tie), overlapping changes are grouped into regions,
 * and each region is resolved by comparing mine's, the base's and theirs's
 * lines for that stretch.
 *
 * Returns an ordered list of regions, each one of:
 *   { kind: 'stable', lines }
 *   { kind: 'mine' | 'theirs' | 'both', lines }
 *   { kind: 'conflict', mine, base, theirs }
 */
export function buildRegions(mineLines, baseLines, theirsLines) {
  const mineChanges = diffChanges(baseLines, mineLines).map(c => ({ ...c, side: 'mine' }))
  const theirsChanges = diffChanges(baseLines, theirsLines).map(c => ({ ...c, side: 'theirs' }))

  const allChanges = [...mineChanges, ...theirsChanges].sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const regions = []
  let cursor = 0
  let index = 0
  while (index < allChanges.length) {
    const first = allChanges[index]
    let start = first.baseStart
    let end = first.baseEnd
    const group = [first]
    index++
    while (index < allChanges.length && allChanges[index].baseStart <= end) {
      const next = allChanges[index]
      if (next.baseEnd > end) end = next.baseEnd
      group.push(next)
      index++
    }

    if (start > cursor) {
      regions.push({ kind: 'stable', lines: baseLines.slice(cursor, start) })
    }
    regions.push(resolveRegion(baseLines, start, end, group))
    cursor = end
  }
  if (cursor < baseLines.length) {
    regions.push({ kind: 'stable', lines: baseLines.slice(cursor, baseLines.length) })
  }

  return regions
}

function resolveRegion(baseLines, start, end, changes) {
  const ownMine = changes.filter(c => c.side === 'mine')
  const ownTheirs = changes.filter(c => c.side === 'theirs')

  const mine = reconstructSide(baseLines, start, end, ownMine)
  const theirs = reconstructSide(baseLines, start, end, ownTheirs)
  const base = baseLines.slice(start, end)

  if (linesEqual(mine, theirs)) {
    const kind = ownMine.length > 0 && ownTheirs.length > 0 ? 'both' : ownMine.length > 0 ? 'mine' : 'theirs'
    return { kind, lines: mine }
  }
  if (linesEqual(mine, base)) {
    return { kind: 'theirs', lines: theirs }
  }
  if (linesEqual(theirs, base)) {
    return { kind: 'mine', lines: mine }
  }
  return { kind: 'conflict', mine, base, theirs }
}
"}

