import { readFileSync } from 'node:fs'
import { buildRegions } from './regions.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function splitDocuments(lines) {
  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      parts.push([])
    } else {
      parts[parts.length - 1].push(line)
    }
  }
  return parts
}

function renderMerge(regions, withBase) {
  const out = []
  let conflicted = false
  for (const region of regions) {
    if (region.kind === 'conflict') {
      conflicted = true
      out.push('<<<<<<< mine')
      out.push(...region.mine)
      if (withBase) {
        out.push('||||||| base')
        out.push(...region.base)
      }
      out.push('=======')
      out.push(...region.theirs)
      out.push('>>>>>>> theirs')
    } else {
      out.push(...region.lines)
